+
+// Logitech HID++ 2.0 short frames for mice behind a LIGHTSPEED receiver
+// (usage page FF00). Layout per Logitech's public HID++ 1.0/2.0 protocol
+// documentation; semantics cross-checked against Solaar (pwr-Solaar/Solaar,
+// GPL-2.0) as protocol evidence — implementation written from scratch here.
+//
+// On a LIGHTSPEED receiver the two vendor collections split the two report
+// widths: FF00/0x01 carries the 7-byte short report (0x10) and FF00/0x02 the
+// 20-byte long report (0x11). Receiver registers answer short frames on the
+// first collection; frames addressed to the paired device are only relayed
+// as long frames through the second — a short device frame gets the HID++ 1.0
+// error 0x09 there. Device frames below are therefore long.
+// Frame: report id, device index, feature index, (function << 4) | software
+// id, then params. Replies echo the first four bytes; feature notifications
+// carry software id 0, so they never match a request.
+pub const HIDPP_SHORT: u8 = 0x10;
+pub const HIDPP_LONG: u8 = 0x11;
+/// Solaar's table of in-use software ids reserves 0x07 (OpenRGB), 0x0A
+/// (LGSTray), 0x0D (G HUB) and 0 (notifications/firmware); avoid them all.
+pub const HIDPP_SOFTWARE_ID: u8 = 0x0b;
+/// Root.Ping: feature 0x00, function 1. Replies echo the mark byte.
+const HIDPP_PING_ADDRESS: u8 = 0x10 | HIDPP_SOFTWARE_ID;
+const HIDPP_PING_MARK: u8 = 0x42;
+
+pub const HIDPP_FEATURE_DEVICE_NAME: u16 = 0x0003;
+pub const HIDPP_FEATURE_BATTERY_STATUS: u16 = 0x1000;
+pub const HIDPP_FEATURE_BATTERY_VOLTAGE: u16 = 0x1001;
+pub const HIDPP_FEATURE_UNIFIED_BATTERY: u16 = 0x1004;
+
+/// Root.GetFeature maps a feature id to the device-local feature index.
+pub fn hidpp_get_feature(device: u8, feature: u16) -> [u8; 20] {
+    let mut frame = [0; 20];
+    frame[..6].copy_from_slice(&[
+        HIDPP_LONG,
+        device,
+        0x00,
+        HIDPP_SOFTWARE_ID,
+        (feature >> 8) as u8,
+        feature as u8,
+    ]);
+    frame
+}
+
+/// Root.Ping; the reply carries the protocol version and echoes the mark.
+pub fn hidpp_ping(device: u8) -> [u8; 20] {
+    let mut frame = [0; 20];
+    frame[..7].copy_from_slice(&[
+        HIDPP_LONG,
+        device,
+        0x00,
+        HIDPP_PING_ADDRESS,
+        0,
+        0,
+        HIDPP_PING_MARK,
+    ]);
+    frame
+}
+
+pub fn hidpp_feature_call(device: u8, index: u8, function: u8) -> [u8; 20] {
+    let mut frame = [0; 20];
+    frame[..4].copy_from_slice(&[
+        HIDPP_LONG,
+        device,
+        index,
+        (function << 4) | HIDPP_SOFTWARE_ID,
+    ]);
+    frame
+}
+
+/// The caller passes params[0], e.g. the character offset for a name chunk.
+pub fn hidpp_feature_call1(device: u8, index: u8, function: u8, param: u8) -> [u8; 20] {
+    let mut frame = hidpp_feature_call(device, index, function);
+    frame[4] = param;
+    frame
+}
+
+fn hidpp_reply_ok(report: &[u8], device: u8, feature: u8, address: u8) -> bool {
+    report.len() >= 7
+        && matches!(report[0], HIDPP_SHORT | HIDPP_LONG)
+        && report[1] == device
+        && report[2] == feature
+        && report[3] == address
+}
+
+pub fn hidpp_ping_reply(report: &[u8], device: u8) -> Option<(u8, u8)> {
+    hidpp_reply_ok(report, device, 0x00, HIDPP_PING_ADDRESS).then(|| (report[4], report[5]))
+}
+
+/// GetFeature replies with the local index, 0 when the device lacks it.
+pub fn hidpp_feature_index(report: &[u8], device: u8) -> Option<u8> {
+    hidpp_reply_ok(report, device, 0x00, HIDPP_SOFTWARE_ID)
+        .then(|| report[4])
+        .filter(|index| *index != 0)
+}
+
+/// Unified Battery GetStatus: (state of charge, level approximation, charge
+/// status). A state of charge of 0 means "not reported"; fall back to the
+/// approximation exactly like Solaar: 8→90, 4→50, 2→20, 1→5, else nothing.
+pub fn hidpp_unified_battery(report: &[u8], device: u8, index: u8) -> Option<u8> {
+    hidpp_reply_ok(report, device, index, (1 << 4) | HIDPP_SOFTWARE_ID)
+        .then(|| match (report[4], report[5]) {
+            (0, 8) => 90,
+            (0, 4) => 50,
+            (0, 2) => 20,
+            (0, 1) => 5,
+            (level, _) => level,
+        })
+        .filter(|level| (1..=100).contains(level))
+}
+
+/// Battery Level Status: (charge level, next level, discharge status); a
+/// level of 0 is "unknown", not empty.
+pub fn hidpp_battery_status(report: &[u8], device: u8, index: u8) -> Option<u8> {
+    hidpp_reply_ok(report, device, index, HIDPP_SOFTWARE_ID)
+        .then(|| report[4])
+        .filter(|level| (1..=100).contains(level))
+}
+
+/// Battery Voltage (0x1001): [voltage_hi, voltage_lo, flags]; flags bit 7 is
+/// the charging indicator. Returns (millivolt, charging).
+pub fn hidpp_voltage_battery(report: &[u8], device: u8, index: u8) -> Option<(u16, bool)> {
+    hidpp_reply_ok(report, device, index, HIDPP_SOFTWARE_ID).then(|| {
+        (
+            u16::from_be_bytes([report[4], report[5]]),
+            report[6] & (1 << 7) != 0,
+        )
+    })
+}
+
+/// Charge percentage estimated from a Battery Voltage reading. Gaming mice
+/// report millivolt, so the discharge curve is modelled: the measured
+/// single-cell Li-Po table below matches Solaar's
+/// `estimate_battery_level_percentage`, with linear interpolation between
+/// points (OpenLogi documents the same derivation).
+pub fn hidpp_voltage_percent(millivolt: u16) -> u8 {
+    const CURVE: [(u16, u8); 13] = [
+        (4186, 100),
+        (4067, 90),
+        (3989, 80),
+        (3922, 70),
+        (3859, 60),
+        (3811, 50),
+        (3778, 40),
+        (3751, 30),
+        (3717, 20),
+        (3671, 10),
+        (3646, 5),
+        (3579, 2),
+        (3500, 0),
+    ];
+    let (top_mv, top_percent) = CURVE[0];
+    if millivolt >= top_mv {
+        return top_percent;
+    }
+    for (&(high_mv, high_percent), &(low_mv, low_percent)) in CURVE.iter().zip(CURVE.iter().skip(1))
+    {
+        if millivolt >= low_mv {
+            let span_mv = u32::from(high_mv - low_mv);
+            let span_percent = u32::from(high_percent - low_percent);
+            let above_low = u32::from(millivolt - low_mv);
+            let interpolated =
+                u32::from(low_percent) + (span_percent * above_low + span_mv / 2) / span_mv;
+            return u8::try_from(interpolated).unwrap_or(high_percent);
+        }
+    }
+    0
+}
+
+/// Battery Voltage reading collapsed to the displayed percentage.
+pub fn hidpp_voltage_battery_percent(report: &[u8], device: u8, index: u8) -> Option<u8> {
+    hidpp_voltage_battery(report, device, index).and_then(|(millivolt, _charging)| {
+        let percent = hidpp_voltage_percent(millivolt);
+        (percent > 0).then_some(percent)
+    })
+}
+
+/// Device name replies carry raw bytes, so UTF-8 sequences split across
+/// short-frame chunks stay decodable by the caller.
+pub fn hidpp_name_length(report: &[u8], device: u8, index: u8) -> Option<usize> {
+    hidpp_reply_ok(report, device, index, HIDPP_SOFTWARE_ID)
+        .then(|| report[4] as usize)
+        .filter(|length| *length > 0 && *length <= 32)
+}
+
+pub fn hidpp_name_text(report: &[u8], device: u8, index: u8) -> Option<&[u8]> {
+    hidpp_reply_ok(report, device, index, (1 << 4) | HIDPP_SOFTWARE_ID).then(|| &report[4..])
+}
+
+// Unifying-family receiver registers; the Lightspeed receiver speaks the same
+// HID++ 1.0 register protocol (cross-checked against Solaar and OpenLogi,
+// which both classify 046d:C539 as Unifying-compatible). Requests go out as
+// [0x10, device, 0x81/0x80, register, three bytes]; replies echo sub id and
+// register, and 1.0 errors arrive as [0x8f, sub id, register, code].
+pub const HIDPP_GET_REGISTER: u8 = 0x81;
+pub const HIDPP_SET_REGISTER: u8 = 0x80;
+/// Notification flags, 24-bit big-endian: bit 8 enables the wireless
+/// device-connection notifications the slot enumeration relies on.
+pub const HIDPP_REGISTER_NOTIFICATIONS: u8 = 0x00;
+/// Connection states: read reports the pairing count, writing 0x02 0x00 0x00
+/// makes the receiver re-broadcast one 0x41 arrival per paired slot.
+pub const HIDPP_REGISTER_CONNECTIONS: u8 = 0x02;
+
+pub fn hidpp_get_register(device: u8, register: u8) -> [u8; 7] {
+    [HIDPP_SHORT, device, HIDPP_GET_REGISTER, register, 0, 0, 0]
+}
+
+pub fn hidpp_set_register(device: u8, register: u8, values: [u8; 3]) -> [u8; 7] {
+    [
+        HIDPP_SHORT,
+        device,
+        HIDPP_SET_REGISTER,
+        register,
+        values[0],
+        values[1],
+        values[2],
+    ]
+}
+
+pub fn hidpp_get_register_reply(report: &[u8], device: u8, register: u8) -> Option<[u8; 3]> {
+    hidpp_reply_ok(report, device, HIDPP_GET_REGISTER, register)
+        .then_some([report[4], report[5], report[6]])
+}
+
+pub fn hidpp_set_register_ok(report: &[u8], device: u8, register: u8) -> bool {
+    hidpp_reply_ok(report, device, HIDPP_SET_REGISTER, register)
+}
+
+/// The pairing count sits in the second byte of the connections register.
+pub fn hidpp_pairing_count(reply: [u8; 3]) -> u8 {
+    reply[1]
+}
+
+/// A `0x41` device-connection notification: [0x10, slot, 0x41, address,
+/// protocol, device info, wpid low, (wpid high truncated in short frames)].
+/// Device-info bit 6 set means the link is not established; the wpid reads
+/// with data[2] as the high byte and data[1] as the low byte (Solaar:
+/// `data[2:3] + data[1:2]`), so `…41 0c 22 7f 40` is wpid 0x407F.
+pub fn hidpp_connection_notification(report: &[u8]) -> Option<(u8, bool, u16)> {
+    (report.len() >= 7 && report[2] == 0x41).then(|| {
+        (
+            report[1],
+            report[4] & (1 << 6) == 0,
+            u16::from_be_bytes([report[6], report[5]]),
+        )
+    })
+}
+
+// Aula command protocol: the 32-byte vendor frames Aula Hub 2.2.3 exchanges
+// with its SDK-channel keyboards (usage page FF60/FF68/FF80 collections on
+// VID 0x0C45, e.g. the F87ProV2-series dongles). Layout and the battery
+// exchange come from the deobfuscated renderer SDK (encodeReadKeyboardData-
+// Command / decodeReadKeyboardDataResponse): [0] = cmd, [1] = mode, [6..8] =
+// CRC-16/CCITT-FALSE over all 32 bytes with those two zeroed, stored low
+// byte first. Replies echo cmd/mode, carry a status byte at [2] that must be
+// 0, and the vendor code never checks their CRC — neither do we.
+pub const AULA_CMD_BATTERY: u8 = 0x11;
+pub const AULA_CMD_BATTERY_ALT: u8 = 0x51;
+pub const AULA_MODE_BATTERY: u8 = 0x16;
+
+/// CRC-16/CCITT-FALSE (poly 0x1021, init 0xFFFF, no reflection); check value
+/// for "123456789" is 0x29B1.
+pub fn aula_crc16(bytes: &[u8]) -> u16 {
+    let mut crc: u16 = 0xffff;
+    for &byte in bytes {
+        crc ^= u16::from(byte) << 8;
+        for _ in 0..8 {
+            crc = if crc & 0x8000 != 0 {
+                (crc << 1) ^ 0x1021
+            } else {
+                crc << 1
+            };
+        }
+    }
+    crc
+}
+
+/// One 32-byte command frame; the CRC slot sits zeroed inside the sum.
+pub fn aula_command_request(cmd: u8, mode: u8) -> [u8; 32] {
+    let mut frame = [0u8; 32];
+    frame[0] = cmd;
+    frame[1] = mode;
+    let crc = aula_crc16(&frame);
+    frame[6] = crc as u8;
+    frame[7] = (crc >> 8) as u8;
+    frame
+}
+
+/// The battery reply for mode 22: level at [8], charging flag at [9]. The
+/// hub parses both as decimal strings; 0 is not a level it ever acts on, so
+/// the same 1..=100 rule as the KZZI family applies. Windows reads carry a
+/// report-id prefix (33 bytes) that bare frames lack (32 bytes).
+pub fn aula_command_battery(report: &[u8], cmd: u8) -> Option<(u8, u8)> {
+    let frame: &[u8] = match report.len() {
+        33 => &report[1..33],
+        32 => report,
+        _ => return None,
+    };
+    if frame[0] != cmd || frame[1] != AULA_MODE_BATTERY || frame[2] != 0 {
+        return None;
+    }
+    let (level, state) = (frame[8], frame[9]);
+    ((1..=100).contains(&level)).then_some((level, state))
+}

//! Logitech Unifying-family receivers (Lightspeed, Unifying, Bolt) over
//! HID++. The pairing count comes from a read of the connections register on
//! the FF00/0x01 collection — it counts paired slots, so a paired but asleep
//! mouse is still swept — and every slot is then probed with a long-frame
//! ping through the FF00/0x02 collection, the only path these receivers
//! relay device HID++ through. The scan performs no register writes, so it
//! cannot disturb a working link; the ping itself is the liveness test.
//!
//! The receiver pairing registers (0xB5 long reads) are deliberately not
//! touched: on the Lightspeed C539 the pairing sub-registers never answer at
//! all, and an idle receiver answers the ones that do exist seconds late —
//! both observed on hardware (examples/probe_logitech.rs). Slot kinds and
//! unit serials therefore stay unknown; readings fall back to the port id.
//! HID++ 1.0-only devices answer long pings with an error frame and are left
//! unsupported — Windows exposes the two report widths as separate
//! collections and relaying short device frames through them is not
//! verified.

use crate::{
    devices::{container_id, drain, open_pair, send},
    protocol,
    vendor::{Capabilities, Outcome, VendorAdapter},
};
use hidapi::{DeviceInfo, HidApi, HidDevice};
use std::time::{Duration, Instant};

pub struct LogitechReceiver;

/// Receiver personalities from Solaar's receiver table; all speak the same
/// HID++ device tunnel with the same register set.
#[derive(Clone, Copy)]
enum Receiver {
    Lightspeed,
    Unifying,
    Bolt,
}

impl Receiver {
    fn from_pid(pid: u16) -> Option<Self> {
        match pid {
            // Lightspeed receivers: C539 measured on hardware; siblings per
            // Solaar's KNOWN_RECEIVERS (usb interface 2, same layout).
            0xc539 | 0xc53a | 0xc53d | 0xc53f | 0xc541 | 0xc545 | 0xc547 | 0xc54d => {
                Some(Self::Lightspeed)
            }
            0xc52b | 0xc532 => Some(Self::Unifying),
            0xc548 => Some(Self::Bolt),
            _ => None,
        }
    }
}

impl VendorAdapter for LogitechReceiver {
    fn matches(&self, info: &DeviceInfo) -> bool {
        // The two FF00 collections carry the two report widths — registers
        // and arrival notifications on 0x01, device-tunnelled HID++ on 0x02.
        // The paired devices ride on the receiver's own identity.
        info.vendor_id() == 0x046d
            && info.usage_page() == 0xff00
            && matches!(info.usage(), 0x01 | 0x02)
            && Receiver::from_pid(info.product_id()).is_some()
    }

    fn kind(&self) -> &'static str {
        // The receiver does not name the device behind a slot (the pairing
        // registers that would are out of scope, see the module notes), so
        // the product line default stands.
        "mouse"
    }

    fn capabilities(&self) -> Capabilities {
        Capabilities::BATTERY
    }

    fn read(&self, api: &HidApi, info: &DeviceInfo) -> Outcome {
        self.read_all(api, info)
            .into_iter()
            .next()
            .unwrap_or_default()
    }

    fn read_all(&self, api: &HidApi, info: &DeviceInfo) -> Vec<Outcome> {
        match probe(api, info) {
            Ok(outcomes) if !outcomes.is_empty() => outcomes,
            // The connections register counts paired slots, so pairings the
            // pings cannot reach mean a device that is off or out of range;
            // an empty probe leaves the receiver itself unaccounted for.
            Ok(_) => vec![Outcome {
                message: "设备未响应，请确认设备已开机".into(),
                ..Outcome::default()
            }],
            Err(_) => vec![Outcome {
                message: "读取失败，请重新连接设备后刷新".into(),
                ..Outcome::default()
            }],
        }
    }
}

fn probe(api: &HidApi, info: &DeviceInfo) -> Result<Vec<Outcome>, String> {
    // The receiver exposes two collections of the same page, so the register
    // and tunnel interfaces are re-matched from the device list and grouped
    // by container — one scan result set per physical receiver.
    Receiver::from_pid(info.product_id()).ok_or("未知罗技接收器")?;
    let container = container_id(info);
    let interfaces: Vec<DeviceInfo> = api
        .device_list()
        .filter(|d| LogitechReceiver.matches(d) && container_id(d) == container)
        .cloned()
        .collect();
    let register_info = interfaces
        .iter()
        .find(|info| info.usage() == 0x01)
        .ok_or("接收器缺少寄存器接口")?;
    let tunnel_info = interfaces
        .iter()
        .find(|info| info.usage() == 0x02)
        .ok_or("接收器缺少设备通道接口")?;
    let (reader, writer) = open_pair(api, register_info)?;
    let (tunnel_reader, tunnel_writer) = open_pair(api, tunnel_info)?;
    let mut buffer = [0; 256];
    let Some(paired) = hidpp_register(
        &reader,
        &writer,
        &mut buffer,
        protocol::HIDPP_REGISTER_CONNECTIONS,
        None,
    )?
    .map(protocol::hidpp_pairing_count) else {
        return Ok(Vec::new());
    };
    if paired == 0 {
        return Ok(vec![Outcome {
            message: "接收器上没有已配对的设备".into(),
            ..Outcome::default()
        }]);
    }
    let mut outcomes = Vec::new();
    for slot in 1..=paired.clamp(1, 6) {
        drain(&tunnel_reader);
        send(&tunnel_writer, &protocol::hidpp_ping(slot))?;
        let online = read_matching(
            &tunnel_reader,
            &mut buffer,
            Duration::from_millis(400),
            |report| protocol::hidpp_ping_reply(report, slot),
        )?;
        if online.is_none() {
            continue;
        }
        let battery = hidpp_battery(&tunnel_reader, &tunnel_writer, &mut buffer, slot)?;
        let name =
            hidpp_name(&tunnel_reader, &tunnel_writer, &mut buffer, slot).unwrap_or_default();
        outcomes.push(Outcome {
            battery,
            no_battery: battery.is_none(),
            hardware_name: (!name.is_empty()).then_some(name),
            slot: Some(slot),
            message: "已连接".into(),
            ..Outcome::default()
        });
    }
    Ok(outcomes)
}

/// One bounded read window; non-matching input (notifications, error frames,
/// other devices' traffic) is consumed and skipped.
fn read_matching<T>(
    reader: &HidDevice,
    buffer: &mut [u8; 256],
    timeout: Duration,
    matcher: impl Fn(&[u8]) -> Option<T>,
) -> Result<Option<T>, String> {
    let end = Instant::now() + timeout;
    while Instant::now() < end {
        let n = reader
            .read_timeout(buffer, 100)
            .map_err(|e| e.to_string())?;
        if n == 0 {
            continue;
        }
        if let Some(value) = matcher(&buffer[..n]) {
            return Ok(Some(value));
        }
    }
    Ok(None)
}

/// One HID++ 1.0 receiver register exchange; `values` selects a write
/// (0x80) over a read (0x81). `None` out means the receiver did not answer.
/// 0x41 arrival notifications streamed in between are consumed and skipped.
fn hidpp_register(
    reader: &HidDevice,
    writer: &HidDevice,
    buffer: &mut [u8; 256],
    register: u8,
    values: Option<[u8; 3]>,
) -> Result<Option<[u8; 3]>, String> {
    let frame = match values {
        Some(values) => protocol::hidpp_set_register(0xff, register, values),
        None => protocol::hidpp_get_register(0xff, register),
    };
    drain(reader);
    send(writer, &frame)?;
    let end = Instant::now() + Duration::from_millis(400);
    while Instant::now() < end {
        let n = reader.read_timeout(buffer, 60).map_err(|e| e.to_string())?;
        if n == 0 {
            continue;
        }
        let matched = match values {
            None => protocol::hidpp_get_register_reply(&buffer[..n], 0xff, register),
            Some(_) => {
                protocol::hidpp_set_register_ok(&buffer[..n], 0xff, register).then_some([0, 0, 0])
            }
        };
        if let Some(reply) = matched {
            return Ok(Some(reply));
        }
    }
    Ok(None)
}

/// Unified Battery (0x1004), Battery Level Status (0x1000), then Battery
/// Voltage (0x1001) — Solaar's preference order for HID++ 2.0 devices; the
/// G502 Lightspeed only carries the voltage feature, whose millivolt reading
/// is mapped to a percentage through the discharge curve.
fn hidpp_battery(
    reader: &HidDevice,
    writer: &HidDevice,
    buffer: &mut [u8; 256],
    device: u8,
) -> Result<Option<u8>, String> {
    for (feature, function, parse) in [
        (
            protocol::HIDPP_FEATURE_UNIFIED_BATTERY,
            1u8,
            protocol::hidpp_unified_battery as fn(&[u8], u8, u8) -> Option<u8>,
        ),
        (
            protocol::HIDPP_FEATURE_BATTERY_STATUS,
            0u8,
            protocol::hidpp_battery_status as fn(&[u8], u8, u8) -> Option<u8>,
        ),
        (
            protocol::HIDPP_FEATURE_BATTERY_VOLTAGE,
            0u8,
            protocol::hidpp_voltage_battery_percent as fn(&[u8], u8, u8) -> Option<u8>,
        ),
    ] {
        drain(reader);
        send(writer, &protocol::hidpp_get_feature(device, feature))?;
        let index = read_matching(reader, buffer, Duration::from_millis(400), |report| {
            protocol::hidpp_feature_index(report, device)
        })?;
        let Some(index) = index else { continue };
        drain(reader);
        send(
            writer,
            &protocol::hidpp_feature_call(device, index, function),
        )?;
        let level = read_matching(reader, buffer, Duration::from_millis(400), |report| {
            parse(report, device, index)
        })?;
        if level.is_some() {
            return Ok(level);
        }
    }
    Ok(None)
}

/// Device Name (0x0003): one length call plus fixed-size text chunks. A
/// half-asleep device answers feature lookups inconsistently, so the lookup
/// is retried and the result length- and printability-checked.
fn hidpp_name(
    reader: &HidDevice,
    writer: &HidDevice,
    buffer: &mut [u8; 256],
    device: u8,
) -> Option<String> {
    let mut index = 0u8;
    for _ in 0..2 {
        drain(reader);
        send(
            writer,
            &protocol::hidpp_get_feature(device, protocol::HIDPP_FEATURE_DEVICE_NAME),
        )
        .ok()?;
        if let Ok(Some(found)) =
            read_matching(reader, buffer, Duration::from_millis(400), |report| {
                protocol::hidpp_feature_index(report, device)
            })
        {
            index = found;
            break;
        }
        std::thread::sleep(Duration::from_millis(150));
    }
    let index = (index != 0).then_some(index)?;
    drain(reader);
    send(writer, &protocol::hidpp_feature_call(device, index, 0)).ok()?;
    let length = read_matching(reader, buffer, Duration::from_millis(400), |report| {
        protocol::hidpp_name_length(report, device, index)
    })
    .ok()??;
    let mut raw = Vec::with_capacity(length);
    while raw.len() < length {
        drain(reader);
        send(
            writer,
            &protocol::hidpp_feature_call1(device, index, 1, raw.len() as u8),
        )
        .ok()?;
        let chunk = read_matching(reader, buffer, Duration::from_millis(400), |report| {
            protocol::hidpp_name_text(report, device, index).map(|bytes| bytes.to_vec())
        })
        .ok()??;
        if chunk.is_empty() {
            return None;
        }
        raw.extend_from_slice(&chunk);
